contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, address finalOwner) public payable {
        require(true);
        // First call: as current owner (the test contract is the initial owner), set owner to newOwner.
        bool firstReverted;
        bool firstReturn;
        try c.setOwner(newOwner) returns (bool r) { firstReturn = r; firstReverted = false; } catch { firstReverted = true; }
        require(!firstReverted);

        // Second call: the test contract is no longer owner, but if ownership transfer is immediate and
        // the new owner (this contract) can call again? Wait, msg.sender is still this test contract,
        // not newOwner. The owner is newOwner, so a call from this contract should revert.
        // The rule we want is: after a successful transfer, only the new owner can transfer again.
        // So we test that a second call from the old owner (this contract) now reverts.
        bool secondReverted;
        bool secondReturn;
        try c.setOwner(finalOwner) returns (bool r) { secondReturn = r; secondReverted = false; } catch { secondReverted = true; }

        // General rule: after a successful setOwner(newOwner), the previous owner (this test contract)
        // is no longer authorized, so setOwner must revert for the previous owner.
        assert(secondReverted && c.owner() == newOwner);
    }

    receive() external payable {}
}

